	(function() {
		function labelSortButtons(root) {
			var scope = root || document;
			var buttons = scope.querySelectorAll('button.dt-column-order:not([aria-label])');
			buttons.forEach(function(btn) {
				var header = btn.closest('th');
				if (!header) return;
				// Pull text from the header, but exclude the button's own contents.
				var headerClone = header.cloneNode(true);
				headerClone.querySelectorAll('button').forEach(function(b) { b.remove(); });
				var label = (headerClone.textContent || '').trim().replace(/\s+/g, ' ');
				btn.setAttribute('aria-label', label ? 'Sort by ' + label : 'Sort column');
			});
		}

		function init() {
			labelSortButtons(document);

			// DataTables can re-render headers (responsive resize, redraw, etc.),
			// so watch for new sort buttons and label them as they appear.
			if (typeof MutationObserver === 'function') {
				var mo = new MutationObserver(function(mutations) {
					for (var i = 0; i < mutations.length; i++) {
						var added = mutations[i].addedNodes;
						for (var j = 0; j < added.length; j++) {
							var node = added[j];
							if (node.nodeType !== 1) continue;
							if (node.matches && node.matches('button.dt-column-order')) {
								labelSortButtons(node.parentNode || document);
							} else if (node.querySelectorAll) {
								if (node.querySelector('button.dt-column-order')) {
									labelSortButtons(node);
								}
							}
						}
					}
				});
				mo.observe(document.body, { childList: true, subtree: true });
			}
		}

		if (document.readyState === 'loading') {
			document.addEventListener('DOMContentLoaded', init);
		} else {
			init();
		}
	})();


	(function() {
		// Add whatever extensions you want without "."
		var fileExtensions = ['pdf', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];

		// Create hidden element for screen reader announcement
		var newTabWarning = document.createElement('span');
		newTabWarning.id = 'new-tab-warning';
		newTabWarning.textContent = 'opens in new tab';
		newTabWarning.style.position = 'absolute';
		newTabWarning.style.left = '-10000px';
		newTabWarning.style.width = '1px';
		newTabWarning.style.height = '1px';
		newTabWarning.style.overflow = 'hidden';

		function isFileLink(url) {
			if (!url) return false;

			try {
				var parsed = new URL(url, window.location.origin);
				var pathname = parsed.pathname.toLowerCase();

				return fileExtensions.some(function(ext) {
					return pathname.endsWith('.' + ext);
				});
			} catch (e) {
				// Fallback
				var lower = url.toLowerCase().split('#')[0].split('?')[0];
				return fileExtensions.some(function(ext) {
					return lower.endsWith('.' + ext);
				});
			}
		}

		function isExternalLink(url) {
			if (!url) return false;

			// Skip relative URLs
			if (url.startsWith('/') || url.startsWith('#')) return false;

			// Skip mailto:, tel:, javascript: etc.
			if (url.match(/^(mailto|tel|javascript|data):/i)) return false;

			try {
				var linkHost = new URL(url, window.location.origin).hostname;
				var currentHost = window.location.hostname;

				// Remove 'www.' from both for comparison
				linkHost = linkHost.replace(/^www\./i, '');
				currentHost = currentHost.replace(/^www\./i, '');

				return linkHost !== currentHost;
			} catch (e) {
				return false;
			}
		}

		function setLinkTargets(context) {
			var root = context || document;
			var links = root.querySelectorAll('a[href]');

			links.forEach(function(link) {
				var href = link.getAttribute('href');

				// Check if it's a file link OR external link
				if (!isFileLink(href) && !isExternalLink(href)) return;

				// Set target to _blank unless link explicitly opts into another target.
				// Treat missing target and _self as "no preference" — we'll force _blank.
				if (!link.target || link.target === '_self') {
					link.target = '_blank';
				}

				// Ensure secure rel attributes
				var rel = link.getAttribute('rel') || '';
				if (rel.indexOf('noopener') === -1) {
					rel += (rel ? ' ' : '') + 'noopener';
				}
				if (rel.indexOf('noreferrer') === -1) {
					rel += (rel ? ' ' : '') + 'noreferrer';
				}
				link.setAttribute('rel', rel.trim());

				// Add screen reader announcement using aria-describedby
				var existingDescribedBy = link.getAttribute('aria-describedby');
				if (existingDescribedBy) {
					// Append to existing aria-describedby if it doesn't already include our warning
					if (existingDescribedBy.indexOf('new-tab-warning') === -1) {
